<template>
	<div class="flex min-h-dvh flex-col bg-ui-surface-gray-50">
		<!-- ============ HEADER ============ -->
		<div
			class="sticky top-0 z-30 border-b border-ui-line-gray-200 bg-ui-surface px-5 py-4"
			style="padding-top: calc(1rem + env(safe-area-inset-top))"
		>
			<div class="flex items-center gap-2">
				<RouterLink
					:to="{ name: 'Home' }"
					class="-ml-1 flex h-10 w-10 shrink-0 items-center justify-center rounded-md text-primary transition-colors hover:bg-ui-surface-blue-50 active:bg-ui-surface-blue-100"
					aria-label="Kembali"
				>
					<svg
						xmlns="http://www.w3.org/2000/svg"
						viewBox="0 0 24 24"
						class="h-7 w-7"
						fill="none"
						stroke="currentColor"
						stroke-width="2"
						stroke-linecap="round"
						stroke-linejoin="round"
					>
						<path d="m12 19-7-7 7-7" />
						<path d="M19 12H5" />
					</svg>
				</RouterLink>
				<span class="min-w-0 flex-1 truncate font-medium text-ui-ink-gray-900"
					>Keterlambatan</span
				>
				<span
					v-if="!loading"
					class="shrink-0 rounded-full bg-ui-surface-gray-100 px-2.5 py-0.5 text-xs font-medium text-ui-ink-gray-500"
					>{{ rows.length }}{{ hasMore ? '+' : '' }}</span
				>
			</div>
		</div>

		<!-- ============ KONTEN ============ -->
		<div class="app-container-narrow flex-1 px-4 py-4 md:px-6">
			<pre v-if="error" class="whitespace-pre-wrap py-4 text-sm text-ui-ink-red-600">{{
				error
			}}</pre>

			<template v-else>
				<!-- Yang menunggu tindakan karyawan ditaruh di paling atas: itulah
				     satu-satunya hal di halaman ini yang punya tenggat. -->
				<div
					v-if="ringkasan.perlu_diisi"
					class="mb-4 flex items-start gap-3 rounded-2xl border border-ui-line-amber-200 bg-ui-surface-amber-50 p-4"
				>
					<svg
						xmlns="http://www.w3.org/2000/svg"
						viewBox="0 0 24 24"
						class="mt-0.5 h-5 w-5 shrink-0 text-ui-ink-amber-600"
						fill="none"
						stroke="currentColor"
						stroke-width="2"
						stroke-linecap="round"
						stroke-linejoin="round"
					>
						<circle cx="12" cy="12" r="9" />
						<path d="M12 8v5" />
						<path d="M12 16h.01" />
					</svg>
					<p class="text-sm text-ui-ink-amber-800">
						<span class="font-semibold"
							>{{ ringkasan.perlu_diisi }} keterlambatan belum ada alasannya.</span
						>
						Isi sebelum batasnya lewat — setelah itu tercatat sebagai tidak dimaafkan.
					</p>
				</div>

				<p v-if="loading && !rows.length" class="py-6 text-sm text-ui-ink-gray-500">Memuat…</p>

				<p v-else-if="!rows.length" class="py-10 text-center text-sm text-ui-ink-gray-400">
					Belum ada catatan keterlambatan. Pertahankan.
				</p>

				<div v-else class="space-y-2.5">
					<button
						v-for="row in rows"
						:key="row.name"
						type="button"
						class="w-full rounded-2xl border border-ui-line-gray-100 bg-ui-surface p-4 text-left shadow-sm transition hover:bg-ui-surface-gray-50 active:bg-ui-surface-gray-100"
						@click="buka(row.name)"
					>
						<div class="flex items-start gap-2">
							<span class="min-w-0 flex-1">
								<span
									class="block truncate text-base font-semibold text-ui-ink-gray-900"
									>{{ tanggalPanjang(row.tanggal) }}</span
								>
								<span class="block truncate text-sm text-ui-ink-gray-500"
									>Masuk {{ jam(row.waktu_masuk) }} · terlambat
									{{ durasiMenit(row.menit_terlambat) }}</span
								>
							</span>
							<span
								class="shrink-0 rounded-full px-2.5 py-0.5 text-xs font-medium"
								:class="statusBadge(row.status)"
								>{{ row.status }}</span
							>
						</div>

						<p v-if="row.alasan" class="mt-2.5 line-clamp-2 text-sm text-ui-ink-gray-600">
							{{ row.alasan }}
						</p>

						<p
							v-if="row.boleh_diisi"
							class="mt-2.5 text-sm font-medium text-ui-ink-amber-700"
						>
							{{
								row.status === 'Tidak Dimaafkan'
									? 'Bisa diajukan ulang'
									: 'Perlu diisi'
							}}
							sampai {{ tanggalRingkas(row.batas_pengisian) }}
						</p>
					</button>

					<button
						v-if="hasMore"
						type="button"
						class="w-full rounded-xl border border-ui-line-gray-200 bg-ui-surface py-3 text-base font-medium text-primary transition hover:bg-ui-surface-blue-50 disabled:opacity-60"
						:disabled="loading"
						@click="muatLagi"
					>
						{{ loading ? 'Memuat…' : 'Muat lebih banyak' }}
					</button>
				</div>
			</template>
		</div>
	</div>
</template>

<script setup>
/**
 * Daftar keterlambatan milik karyawan yang sedang login.
 *
 * Record-nya dibuat sistem tiap kali Kehadiran difinalkan dengan tanda
 * terlambat — karyawan tidak pernah membuatnya sendiri, hanya mengisi alasan
 * dari halaman detail.
 *
 * Antrean persetujuan atasan TIDAK ada di sini: halaman Workflow Requests
 * sudah menampilkannya bersama pengajuan cuti dan deviasi.
 */
import { onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { createResource } from 'frappe-ui'
import {
	durasiMenit,
	jam,
	statusBadge,
	tanggalPanjang,
	tanggalRingkas,
} from '../data/keterlambatanStatus'
import { refreshCsrfToken } from '../data/session'

const PER_HALAMAN = 20
const router = useRouter()

const rows = ref([])
const ringkasan = ref({ perlu_diisi: 0, menunggu_keputusan: 0 })
const start = ref(0)
const hasMore = ref(false)
const loading = ref(false)
const error = ref('')

function buka(name) {
	router.push({ name: 'KeterlambatanDetail', params: { name } })
}

const list = createResource({
	url: 'juragan.api.portal.keterlambatan.get_daftar',
	auto: false,
	makeParams() {
		return { limit: PER_HALAMAN, start: start.value }
	},
	onSuccess(data) {
		const batch = data || []
		rows.value = start.value === 0 ? batch : rows.value.concat(batch)
		hasMore.value = batch.length === PER_HALAMAN
		loading.value = false
	},
	onError(err) {
		error.value = err?.messages?.[0] || err?.message || String(err)
		loading.value = false
	},
})

const ringkas = createResource({
	url: 'juragan.api.portal.keterlambatan.get_ringkasan',
	auto: false,
	onSuccess(data) {
		ringkasan.value = data || { perlu_diisi: 0, menunggu_keputusan: 0 }
	},
	// Wajib ada meski tidak berbuat apa-apa: resource tanpa onError membuat
	// error-nya lolos jadi unhandled rejection, dan handler global menampilkan
	// toast KEDUA untuk kegagalan yang sama. Lencana ini pelengkap — kalau
	// gagal, daftarnya sendiri yang sudah menjelaskan.
	onError() {
		ringkasan.value = { perlu_diisi: 0, menunggu_keputusan: 0 }
	},
})

function reload() {
	error.value = ''
	start.value = 0
	loading.value = true
	list.fetch()
	ringkas.fetch()
}

function muatLagi() {
	start.value += PER_HALAMAN
	loading.value = true
	list.fetch()
}

onMounted(async () => {
	await refreshCsrfToken()
	reload()
})
</script>
